import Atomics

/// [REQ-ENG-1/4] Engine facade: host-agnostic render entry + the load-bearing
/// atomic program swap with generation-gated deferred reclamation (spec 01 §1.4).
///
/// P0 limitations (tracked, deliberate):
/// - Commands apply at block start; sample-offset scheduling within the block
///   (AT-ENG-5 second half) lands with the MIDI integration.
/// - FTZ/denormal flushing (§1.2 rule 4) not yet enabled — needs per-arch FPCR
///   code verified on hardware.
public final class Engine {
    public let commandRing: CommandRing
    private let active = ManagedAtomic<UnsafeMutableRawPointer?>(nil)
    private let rtGeneration = ManagedAtomic<UInt64>(0)
    private var retired: [(gen: UInt64, ref: Unmanaged<Program>)] = []   // UI thread only
    private var nextGeneration: UInt64 = 0                               // UI thread only

    public init(commandRingCapacity: Int = 4096) {
        commandRing = CommandRing(capacity: commandRingCapacity)
    }
    deinit {
        if let raw = active.load(ordering: .acquiring) {
            Unmanaged<Program>.fromOpaque(raw).release()
        }
        for r in retired { r.ref.release() }
    }

    /// UI thread. Swaps the active program; never blocks the RT thread.
    public func install(program: Program) {
        nextGeneration += 1
        program.generation = nextGeneration
        let newRaw = Unmanaged.passRetained(program).toOpaque()
        let oldRaw = active.exchange(newRaw, ordering: .acquiringAndReleasing)
        if let oldRaw = oldRaw {
            let old = Unmanaged<Program>.fromOpaque(oldRaw)
            retired.append((gen: old.takeUnretainedValue().generation, ref: old))
        }
        reclaim()
    }

    /// UI thread, poll at display rate. Frees retired programs the RT thread
    /// has provably moved past (rtGeneration >= a program installed AFTER it).
    public func reclaim() {
        let seen = rtGeneration.load(ordering: .acquiring)
        // A retired program (gen g) is safe to free once the RT thread has
        // rendered a block with a NEWER program (seen > g).
        retired.removeAll { entry in
            if seen > entry.gen { entry.ref.release(); return true }
            return false
        }
    }

    /// True when nothing is awaiting reclamation (test hook).
    public var retiredCount: Int { retired.count }

    @discardableResult
    public func send(_ command: ParameterCommand) -> Bool { commandRing.push(command) }

    /// RT thread. Renders into non-interleaved L/R buffers.
    public func render(left: UnsafeMutablePointer<Float>, right: UnsafeMutablePointer<Float>,
                       frameCount: Int, context: RenderContext) {
        guard let raw = active.load(ordering: .acquiring) else {
            for i in 0..<frameCount { left[i] = 0; right[i] = 0 }
            return
        }
        let program = Unmanaged<Program>.fromOpaque(raw).takeUnretainedValue()
        let frames = min(frameCount, program.maxBlockSize)

        // Drain command ring at block start (P0: applied at frame 0).
        while let cmd = commandRing.pop() { program.apply(cmd) }

        program.execute(frames: frames, ctx: context)

        if let l = program.masterL, let r = program.masterR {
            for i in 0..<frames { left[i] = l[i]; right[i] = r[i] }
        } else {
            for i in 0..<frames { left[i] = 0; right[i] = 0 }
        }
        rtGeneration.store(program.generation, ordering: .releasing)
    }
}

