4	final class EngineTests: XCTestCase {
5	    private func sineGraph(freq: Double = 440, gain: Double = 0.5) -> GraphDescription {
6	        GraphDescription(
7	            nodes: [.init(id: 1, kind: .oscillator(frequency: freq, waveform: .sine)),
8	                    .init(id: 2, kind: .vca(gain: gain)),
9	                    .init(id: 3, kind: .audioOut)],
10	            edges: [.init(from: 1, to: 2),
11	                    .init(from: 2, to: 3, toPort: 0),
12	                    .init(from: 2, to: 3, toPort: 1)])
13	    }
14	
15	    /// AT-ENG-1 (subset): frequency accuracy via zero-crossing count.
16	    func testSineFrequencyAccuracy() throws {
17	        for sr in [44100.0, 48000.0, 96000.0] {
18	            let engine = Engine()
19	            engine.install(program: try GraphCompiler.compile(sineGraph(), sampleRate: sr, maxBlockSize: 512))
20	            let ctx = RenderContext(sampleRate: sr)
21	            let seconds = 2.0
