import XCTest
@testable import SynthEngine

final class EngineTests: XCTestCase {
    private func sineGraph(freq: Double = 440, gain: Double = 0.5) -> GraphDescription {
        GraphDescription(
            nodes: [.init(id: 1, kind: .oscillator(frequency: freq, waveform: .sine)),
                    .init(id: 2, kind: .vca(gain: gain)),
                    .init(id: 3, kind: .audioOut)],
            edges: [.init(from: 1, to: 2),
                    .init(from: 2, to: 3, toPort: 0),
                    .init(from: 2, to: 3, toPort: 1)])
    }

    /// AT-ENG-1 (subset): frequency accuracy via zero-crossing count.
    func testSineFrequencyAccuracy() throws {
        for sr in [44100.0, 48000.0, 96000.0] {
            let engine = Engine()
            engine.install(program: try GraphCompiler.compile(sineGraph(), sampleRate: sr, maxBlockSize: 512))
            let ctx = RenderContext(sampleRate: sr)
            let seconds = 2.0
            let total = Int(sr * seconds)
            var signal = [Float](); signal.reserveCapacity(total)
            var l = [Float](repeating: 0, count: 512), r = [Float](repeating: 0, count: 512)
            var rendered = 0
            while rendered < total {
                let n = min(512, total - rendered)
                l.withUnsafeMutableBufferPointer { lp in
                    r.withUnsafeMutableBufferPointer { rp in
                        engine.render(left: lp.baseAddress!, right: rp.baseAddress!, frameCount: n, context: ctx)
                    }
                }
                signal.append(contentsOf: l[0..<n]); rendered += n
            }
            var crossings = 0
            for i in 1..<signal.count where signal[i-1] < 0 && signal[i] >= 0 { crossings += 1 }
            let measured = Double(crossings) / seconds
            XCTAssertEqual(measured, 440.0, accuracy: 1.0, "at \(sr) Hz")
        }
    }

    /// AT-ENG-4 (the swap-hammer, P0 exit criterion): 1000 program swaps during
    /// rendering; output must stay a continuous sine — no steps, no dropouts.
    func testSwapHammerGlitchFree() throws {
        let sr = 48000.0, block = 128, swaps = 1000
        let engine = Engine()
        let initial = try GraphCompiler.compile(sineGraph(), sampleRate: sr, maxBlockSize: block)
        engine.install(program: initial)

        let stop = ManagedAtomicBool()
        let swapper = Thread {
            var previous: Program? = initial
            for i in 0..<swaps {
                var g = self.sineGraph()
                if i % 10 == 0 {   // every 10th swap adds a disconnected extra node
                    g.nodes.append(.init(id: 99, kind: .vca(gain: 1.0)))
                }
                if let p = try? GraphCompiler.compile(g, sampleRate: sr, maxBlockSize: block, reusing: previous) {
                    engine.install(program: p)
                    previous = p
                }
            }
            stop.set()
        }
        swapper.start()

        var signal: [Float] = []
        var l = [Float](repeating: 0, count: block), r = [Float](repeating: 0, count: block)
        let ctx = RenderContext(sampleRate: sr)
        while !stop.get() || signal.count < block * 200 {
            l.withUnsafeMutableBufferPointer { lp in
                r.withUnsafeMutableBufferPointer { rp in
                    engine.render(left: lp.baseAddress!, right: rp.baseAddress!, frameCount: block, context: ctx)
                }
            }
            signal.append(contentsOf: l)
            if signal.count > 48000 * 30 { break }  // safety bound
        }
        engine.reclaim()

        // (a) continuity: max step of a clean 440 Hz sine at amp 0.5 is
        //     0.5 * 2π * 440/48000 ≈ 0.0288; allow smoothing/settle margin.
        var maxStep: Float = 0
        for i in 1..<signal.count { maxStep = max(maxStep, abs(signal[i] - signal[i-1])) }
        XCTAssertLessThan(maxStep, 0.035, "discontinuity implies a glitch during swap")
        // (b) no dropped/zeroed blocks after the first one
        var zeroRun = 0, worstZeroRun = 0
        for s in signal.dropFirst(block) {
            zeroRun = (s == 0) ? zeroRun + 1 : 0
            worstZeroRun = max(worstZeroRun, zeroRun)
        }
        XCTAssertLessThan(worstZeroRun, 8, "sustained zeros imply a dropout")
        // (c) it's actually audible signal
        let rms = (signal.reduce(Float(0)) { $0 + $1 * $1 } / Float(signal.count)).squareRoot()
        XCTAssertGreaterThan(rms, 0.2)
    }

    /// REQ-ENG-4: retired programs are reclaimed once the RT thread moves past them.
    func testDeferredReclamation() throws {
        let engine = Engine()
        let ctx = RenderContext(sampleRate: 48000)
        var l = [Float](repeating: 0, count: 64), r = [Float](repeating: 0, count: 64)
        for _ in 0..<5 {
            engine.install(program: try GraphCompiler.compile(sineGraph(), sampleRate: 48000, maxBlockSize: 64))
        }
        XCTAssertGreaterThan(engine.retiredCount, 0)
        l.withUnsafeMutableBufferPointer { lp in
            r.withUnsafeMutableBufferPointer { rp in
                engine.render(left: lp.baseAddress!, right: rp.baseAddress!, frameCount: 64, context: ctx)
            }
        }
        engine.reclaim()
        XCTAssertEqual(engine.retiredCount, 0)
    }

    func testCycleRejected() {
        let g = GraphDescription(
            nodes: [.init(id: 1, kind: .vca(gain: 1)), .init(id: 2, kind: .vca(gain: 1))],
            edges: [.init(from: 1, to: 2), .init(from: 2, to: 1)])
        XCTAssertThrowsError(try GraphCompiler.compile(g, sampleRate: 48000, maxBlockSize: 64)) {
            XCTAssertEqual($0 as? CompileError, .cycle)
        }
    }

    /// REQ-ENG-5 partial: smoothedSet ramps without clicks (block-start apply).
    func testParameterSmoothingNoClick() throws {
        let engine = Engine()
        engine.install(program: try GraphCompiler.compile(sineGraph(freq: 440, gain: 0.0),
                                                          sampleRate: 48000, maxBlockSize: 128))
        let ctx = RenderContext(sampleRate: 48000)
        var l = [Float](repeating: 0, count: 128), r = [Float](repeating: 0, count: 128)
        var signal: [Float] = []
        engine.send(ParameterCommand(nodeID: 2, paramID: 0, kind: .smoothedSet, value: 1.0, sampleTime: -1))
        for _ in 0..<80 {   // ~213 ms
            l.withUnsafeMutableBufferPointer { lp in
                r.withUnsafeMutableBufferPointer { rp in
                    engine.render(left: lp.baseAddress!, right: rp.baseAddress!, frameCount: 128, context: ctx)
                }
            }
            signal.append(contentsOf: l)
        }
        var maxStep: Float = 0
        for i in 1..<signal.count { maxStep = max(maxStep, abs(signal[i] - signal[i-1])) }
        XCTAssertLessThan(maxStep, 0.08, "gain jump not smoothed")
        let tail = signal.suffix(4096)
        let rms = (tail.reduce(Float(0)) { $0 + $1 * $1 } / Float(tail.count)).squareRoot()
        XCTAssertGreaterThan(rms, 0.5, "gain never reached target")
    }
}

/// Minimal atomic bool for test thread signaling.
private final class ManagedAtomicBool: @unchecked Sendable {
    private let lock = NSLock()
    private var v = false
    func set() { lock.lock(); v = true; lock.unlock() }
    func get() -> Bool { lock.lock(); defer { lock.unlock() }; return v }
}

